DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `AddAsset` (IN `campus_code_param` VARCHAR(20), IN `building_name_param` VARCHAR(100), IN `category_code_param` VARCHAR(20), IN `room_param` VARCHAR(100), IN `model_no_param` VARCHAR(100), IN `serial_no_param` VARCHAR(100), IN `brand_param` VARCHAR(100), IN `capacity_param` VARCHAR(50), IN `price_param` DECIMAL(10,2), IN `condition_param` VARCHAR(50))   BEGIN
    DECLARE campus_id_var INT;
    DECLARE building_id_var INT;
    DECLARE category_id_var INT;
    
    -- Get IDs
    SELECT campus_id INTO campus_id_var FROM campuses WHERE campus_code = campus_code_param;
    SELECT building_id INTO building_id_var FROM buildings WHERE building_name = building_name_param AND campus_id = campus_id_var;
    SELECT category_id INTO category_id_var FROM categories WHERE category_code = category_code_param;
    
    -- Insert asset
    INSERT INTO assets (campus_id, building_id, category_id, room, model_no, serial_no, brand, capacity, price, asset_condition)
    VALUES (campus_id_var, building_id_var, category_id_var, room_param, model_no_param, serial_no_param, brand_param, capacity_param, price_param, condition_param);
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `GetCampusAssets` (IN `campus_code_param` VARCHAR(20))   BEGIN
    SELECT 
        b.building_name,
        cat.category_name,
        a.*
    FROM assets a
    JOIN campuses c ON a.campus_id = c.campus_id
    JOIN buildings b ON a.building_id = b.building_id
    JOIN categories cat ON a.category_id = cat.category_id
    WHERE c.campus_code = campus_code_param
    ORDER BY b.building_name, cat.category_name;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `GetCampusSummary` (IN `campus_code_param` VARCHAR(20))   BEGIN
    SELECT 
        c.campus_name,
        cat.category_name,
        cat.description,
        cat.icon,
        COUNT(a.asset_id) as total_units,
        COUNT(DISTINCT b.building_id) as building_count
    FROM campuses c
    LEFT JOIN assets a ON c.campus_id = a.campus_id
    LEFT JOIN categories cat ON a.category_id = cat.category_id
    LEFT JOIN buildings b ON a.building_id = b.building_id
    WHERE c.campus_code = campus_code_param
    GROUP BY c.campus_id, cat.category_id;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_calculate_statement_totals` (IN `p_statement_id` INT)   BEGIN
  DECLARE v_revenue DECIMAL(15,2);
  DECLARE v_less DECIMAL(15,2);
  DECLARE v_other_income DECIMAL(15,2);
  DECLARE v_repair DECIMAL(15,2);
  DECLARE v_total_revenue DECIMAL(15,2);
  DECLARE v_total_expenses DECIMAL(15,2);
  DECLARE v_net_income DECIMAL(15,2);
  
  -- Get category totals
  SELECT COALESCE(SUM(amount), 0) INTO v_revenue 
  FROM income_statement_items 
  WHERE statement_id = p_statement_id AND category = 'revenue';
  
  SELECT COALESCE(SUM(amount), 0) INTO v_less 
  FROM income_statement_items 
  WHERE statement_id = p_statement_id AND category = 'less';
  
  SELECT COALESCE(SUM(amount), 0) INTO v_other_income 
  FROM income_statement_items 
  WHERE statement_id = p_statement_id AND category = 'other_income';
  
  SELECT COALESCE(SUM(amount), 0) INTO v_repair 
  FROM income_statement_items 
  WHERE statement_id = p_statement_id AND category = 'repair';
  
  -- Calculate totals
  SET v_total_revenue = v_revenue;
  SET v_total_expenses = v_less + v_repair;
  SET v_net_income = v_revenue - v_less + v_other_income - v_repair;
  
  -- Update statement
  UPDATE income_statements 
  SET 
    total_revenue = v_total_revenue,
    total_expenses = v_total_expenses,
    net_income = v_net_income
  WHERE id = p_statement_id;
  
END$$

DELIMITER ;

